package com.clara.adapter.cli;import com.clara.kernel.*;public final class CliExitCodes {public static final int SUCCESS=0,INVALID=2,WAITING_INPUT=3,FAILED=4,DENIED=5,EXTERNAL_UNAVAILABLE=6;private CliExitCodes(){}public static int from(ClaraError error){if(error==null)return FAILED;switch(error.getCategory()){case AUTHENTICATION:case AUTHORIZATION:return DENIED;case CAPABILITY:case EXTERNAL_SERVICE:case RATE_LIMIT:case TIMEOUT:return EXTERNAL_UNAVAILABLE;case CONFIGURATION:case VALIDATION:return INVALID;default:return FAILED;}}}
